"use client";

import { useState } from "react";
import { SubHeader } from "../components/SubHeader";
import { transferDemoTicket, useDemoState, type DemoTicket } from "../lib/demo-store";

export default function TicketsPage() {
  const demo = useDemoState();
  const [tab, setTab] = useState<"active" | "past">("active");
  const [modal, setModal] = useState<"qr" | "transfer" | null>(null);
  const [selectedTicket, setSelectedTicket] = useState<DemoTicket | null>(null);
  const activeDemoTickets = demo.tickets.filter(ticket => ticket.status === "AKTİF");

  function openModal(type: "qr" | "transfer", ticket: DemoTicket | null = null) {
    setSelectedTicket(ticket);
    setModal(type);
  }

  function completeTransfer() {
    if (selectedTicket) transferDemoTicket(selectedTicket.id);
    setModal(null);
  }

  return <main className="wallet-page"><SubHeader active="tickets" /><section className="wallet-head"><span className="section-kicker">ETKİNLİK CÜZDANIN</span><h1>Anıların ve<br /><em>gelecek planların.</em></h1><div><button className={tab === "active" ? "active" : ""} onClick={() => setTab("active")} type="button">Yaklaşan <span>{2 + activeDemoTickets.length}</span></button><button className={tab === "past" ? "active" : ""} onClick={() => setTab("past")} type="button">Geçmiş <span>{12 + demo.tickets.length - activeDemoTickets.length}</span></button></div></section>{tab === "active" ? <section className="wallet-list">{activeDemoTickets.map(ticket => <article className="wallet-ticket demo-wallet-ticket" key={ticket.id}><div className={`wallet-art ${ticket.category === "Konser" ? "art-concert" : ""}`}><span>YENİ DEMO BİLETİ</span><strong>{ticket.eventTitle.split(" ").slice(0,3).map(word => <i key={word}>{word}<br /></i>)}</strong><em>{ticket.date}</em></div><div className="wallet-info"><span>TEST SATIŞI TAMAMLANDI</span><h2>{ticket.eventTitle}</h2><p>{ticket.date} 2026 · {ticket.time}</p><p>{ticket.place} · {ticket.city}</p><div><span><small>KOLTUK</small><strong>{ticket.seats.join(", ")}</strong></span><span><small>SİPARİŞ</small><strong>{ticket.orderNumber}</strong></span><span><small>TUTAR</small><strong>{ticket.total.toLocaleString("tr-TR")} TL</strong></span></div><button type="button" onClick={() => openModal("qr", ticket)}>QR bileti aç <span>▦</span></button><button className="transfer-btn" type="button" onClick={() => openModal("transfer", ticket)}>Bileti transfer et</button></div></article>)}<article className="wallet-ticket primary-ticket"><div className="wallet-art"><span>STAND-UP</span><strong>İLİŞKİ<br /><i>TESTİ</i></strong><em>12 EYL</em></div><div className="wallet-info"><span>4 GÜN KALDI</span><h2>Mesut Süre ile İlişki Testi</h2><p>12 Eylül Cumartesi · 20:30</p><p>Milyon Performance Hall · Ankara</p><div><span><small>KOLTUK</small><strong>B5 · VIP</strong></span><span><small>SİPARİŞ</small><strong>BLŞ-26-10482</strong></span></div><button type="button" onClick={() => openModal("qr")}>QR bileti aç <span>▦</span></button><button className="transfer-btn" type="button" onClick={() => openModal("transfer")}>Bileti transfer et</button></div></article><article className="wallet-ticket compact-ticket"><div className="wallet-art art-concert"><span>KONSER</span><strong>FATİH<br /><i>TURNESİ</i></strong><em>21 EYL</em></div><div className="wallet-info"><span>13 GÜN KALDI</span><h2>Mabel Matiz — Fatih Turnesi</h2><p>21 Eylül Pazartesi · 21:00</p><p>ODTÜ Vişnelik · Ankara</p><div><span><small>BİLET</small><strong>Genel Alan · 2 kişi</strong></span></div><button type="button" onClick={() => openModal("qr")}>QR bileti aç <span>▦</span></button></div></article></section> : <section className="past-events"><div>✓</div><h2>{12 + demo.tickets.length - activeDemoTickets.length} güzel anı biriktirdin</h2><p>Geçmiş ve transfer edilen biletlerin burada saklanıyor.</p><a href="/discover">Yeni bir plan bul →</a></section>}{modal && <div className="modal-backdrop" onClick={() => setModal(null)}><div className="ticket-modal" onClick={event => event.stopPropagation()}><button type="button" onClick={() => setModal(null)}>×</button>{modal === "qr" ? <><span className="status-active">AKTİF {selectedTicket ? "DEMO " : ""}BİLET</span><h2>{selectedTicket?.eventTitle || "İlişki Testi"}</h2><p>{selectedTicket ? `${selectedTicket.date} · ${selectedTicket.seats.join(", ")}` : "12 Eylül · B5 VIP"}</p><div className="qr-pattern" aria-label="Örnek QR bilet deseni">{Array.from({ length: 81 }, (_, index) => <i className={[0,1,2,9,11,18,19,20,6,7,8,15,17,24,25,26,40,42,44,46,48,54,55,57,59,61,63,65,67,72,73,74,78,79,80].includes(index) ? "dark" : ""} key={index} />)}</div><small>{selectedTicket?.qr || "BLŞ-26-10482-B5"}</small><div className="qr-warning">Demo QR kodudur. Gerçek turnikede geçerli değildir.</div></> : <><span className="status-active">GÜVENLİ DEMO TRANSFER</span><h2>Bileti bir arkadaşına gönder</h2><p>Onayladığında demo bilet geçmiş biletler alanına taşınır.</p><label>Telefon veya e-posta<input placeholder="05XX XXX XX XX" /></label><button className="modal-main-button" onClick={completeTransfer} type="button">Transferi tamamla →</button></>}</div></div>}</main>;
}
