"use client";
import { useState } from "react";
import { SubHeader } from "../components/SubHeader";

export default function MatchPage(){
  const [started,setStarted]=useState(false),[accepted,setAccepted]=useState(false),[chat,setChat]=useState(false); const [age,setAge]=useState("20–30 yaş"),[style,setStyle]=useState("Yeni insanlara açığım"),[message,setMessage]=useState(""),[messages,setMessages]=useState<string[]>(["Merhaba! Etkinlik öncesi girişte buluşalım mı?"]);
  return <main className="match-page"><SubHeader/><section className="match-hero"><div><span className="section-kicker">YALNIZ GİTME</span><h1>Aynı bilete bakan<br/><em>birini bul.</em></h1><p>Etkinliğini seç, tercihlerini belirle. Demo eşleşme sistemi ortak ilgi ve sosyal uyuma göre sana uygun bir profil gösterir.</p><div className="safety-points"><span>🧪 Demo profil</span><span>✓ Raporlama örneği</span><span>✓ Güven puanı</span></div></div><div className="match-card-stack"><article className="back-card"><span>81</span></article><article className="match-card"><div className="match-avatar">EZ<span>✓</span></div><small>%92 UYUM</small><h2>Elif Z.</h2><p>28 · Ankara</p><div><span>😂 Stand-up</span><span>🎭 Tiyatro</span><span>☕ Sohbet</span></div><hr/><p className="match-event"><b>İlişki Testi</b><span>12 Eylül · Ankara</span></p></article></div></section>{chat?<section className="demo-chat" id="chat"><header><div><span>EZ</span><p><strong>Elif Z.</strong><small>Demo sohbet · çevrimiçi</small></p></div><button type="button" onClick={()=>setChat(false)}>Sohbeti kapat ×</button></header><div>{messages.map((item,index)=><p className={index%2?"mine":""} key={`${item}-${index}`}>{item}</p>)}</div><form onSubmit={event=>{event.preventDefault();if(message.trim()){setMessages([...messages,message.trim()]);setMessage("")}}}><input value={message} onChange={event=>setMessage(event.target.value)} placeholder="Demo mesajını yaz"/><button type="submit">Gönder →</button></form><small>Bu mesajlar yalnızca ekranda tutulur; gerçek bir kişiye gönderilmez.</small></section>:!started?<section className="match-setup"><div className="setup-step"><span>01</span><div><h3>Etkinliği seç</h3><button className="selected" type="button"><b>12 EYL</b><p>Mesut Süre ile İlişki Testi<small>Milyon Performance Hall</small></p><i>✓</i></button></div></div><div className="setup-step"><span>02</span><div><h3>Kiminle tanışmak istersin?</h3><div className="match-options">{["20–30 yaş","30–40 yaş","Yaş önemli değil"].map(item=><button className={age===item?"selected":""} onClick={()=>setAge(item)} type="button" key={item}>{item}</button>)}</div></div></div><div className="setup-step"><span>03</span><div><h3>Sosyal tarzın</h3><div className="match-options">{["Sohbet etmeyi severim","Yeni insanlara açığım","Sessiz takılırım"].map(item=><button className={style===item?"selected":""} onClick={()=>setStyle(item)} type="button" key={item}>{item}</button>)}</div></div></div><button className="start-match" onClick={()=>setStarted(true)} type="button">Eşleşmeyi başlat <span>→</span></button></section>:<section className="match-found"><span className="pulse-ring">✦</span><small>{accepted?"EŞLEŞME TAMAMLANDI":"SANA UYGUN BİRİ VAR"}</small><h2>{accepted?"Demo sohbetiniz hazır!":"%92 uyumlu bir eşleşme bulduk"}</h2><p>{accepted?"Güvenli demo sohbet alanında etkinlik planını test edebilirsin.":`Elif, ${age} tercihin ve “${style}” tarzınla uyumlu görünüyor.`}</p>{accepted?<button type="button" onClick={()=>setChat(true)}>Sohbeti aç →</button>:<div><button onClick={()=>setAccepted(true)} type="button">Tanışmak istiyorum</button><button onClick={()=>setStarted(false)} type="button">Şimdilik geç</button></div>}</section>}</main>
}
