  const search=(event:MouseEvent<HTMLButtonElement>)=>{event.preventDefault();navigateTo(`/discover?query=${encodeURIComponent(query)}&city=${encodeURIComponent(city)}`)};const campaign=campaignSlides[currentSlide];
